matrix_mul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[16][16];
    __shared__ float sB[16][16];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + 15) / 16; ++tile) {
        int tile_row = tile * 16 + threadIdx.y;
        int tile_col = tile * 16 + threadIdx.x;

        if (tile_row < N && threadIdx.x < 16) {
            sA[threadIdx.y][threadIdx.x] = A[row * N + tile_row];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (tile_col < N && threadIdx.y < 16) {
            sB[threadIdx.y][threadIdx.x] = B[tile_col * N + col];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < 16; ++k) {
            sum += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Warp-level reduction to minimize bank conflicts
    for (int offset = 16 / 2; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xFFFFFFFF, sum, offset);
    }

    if (row < N && col < N && threadIdx.x == 0) {
        C[row * N + col] = sum;
    }
}

